bounded_host_request.command:
set -eu
python3 -B - <<'PY'
import json, subprocess, tarfile, io, collections, hashlib
c="debug-ai-debug-ai-1"
ids=["run_mwzbrgyg_c5b2b9b209","run_mwzcqyn6_eaae846a22","run_mwzds6fb_0fc27ef1eb"]
def read_tar(p):
    raw=subprocess.check_output(["docker","cp",c+":"+p,"-"])
    with tarfile.open(fileobj=io.BytesIO(raw)) as t:
        return {m.name:t.extractfile(m).read() for m in t.getmembers() if m.isfile() and m.size<=4000000}
def project(x,keys):
    return {k:x.get(k) for k in keys if k in x}
print("CONTAINER_RUNNING",subprocess.check_output(["docker","inspect","--format","{{.State.Running}}",c],text=True).strip())
for p in ["server/workflow.js","server/adapters/ai-core.js","server/control/real-debug-benchmark.js","server/roles.js","server/control/invocation-compiler.js"]:
    files=read_tar("/app/"+p)
    print("SOURCE",p,[(n,hashlib.sha256(v).hexdigest()) for n,v in files.items()])
for rid in ids:
    records=[]
    for n,b in read_tar("/app/runtime/"+rid).items():
        if not n.endswith(".json"):continue
        try:r=json.loads(b)
        except ValueError:continue
        if r.get("run_id")==rid and r.get("schema")=="runtime-evidence/v1":records.append(r)
    records.sort(key=lambda x:x.get("created_at",""))
    print("RUN",rid,"TYPES",json.dumps(dict(collections.Counter(r.get("type") for r in records))))
    inv={}
    for r in records:
        p=r.get("payload") or {}
        if not isinstance(p,dict):continue
        if r.get("type")=="ai_invocation":
            key=p.get("invocation_id")
            if key:inv[key]=p
        if r.get("type")=="analysis":
            print("ANALYSIS",json.dumps(project(p,["state","diagnosis","local_hypothesis_review","external_hypothesis_review","evidence_gap","evidence_status","role_runtime_telemetry"]),ensure_ascii=False)[:24000])
            print("ANALYSIS_KEYS",list(p))
            reg=p.get("evidence_registry") or {}
            if isinstance(reg,dict):print("REGISTRY",json.dumps(project(reg,["evidence_ids","tool_evidence_ids"])))
            print("SCOUTS",json.dumps(p.get("scouts"),ensure_ascii=False)[:12000])
    for p in inv.values():
        print("INVOCATION",json.dumps(project(p,["invocation_id","role","model","phase","started_at","elapsed_ms","queue_wait_ms","prepare_ms","failure_code","timeout_class","telemetry","upstream_reported_code","dispatch_mode"]),ensure_ascii=False))
PY
